 * Подтема SddsFinAiTheme.Inverse
 */
@Composable
public fun SddsFinAiTheme.Inverse(
    isDark: Boolean = isSystemInDarkTheme(),
    content: @Composable
    () -> Unit,
) {
    val currentColors = LocalSddsFinAiColors.current
    val overrideColors = currentColors.copyAttrs(InverseColorsOverride)
    val currentGradients = LocalSddsFinAiGradients.current
    val overrideGradients = currentGradients.copyAttrs(InverseGradientsOverride)
    SddsFinAiTheme(
        colors = overrideColors,
        gradients = overrideGradients,
        content = content,
    )
}
